using Npgsql; using AvenChart.Api.Models;
namespace AvenChart.Api.Data;
public sealed class PatientEducationRepository(NpgsqlDataSource source){public async Task<PatientEducationResponse> GetAsync(CancellationToken ct){await using var c=await source.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="select resource_key,title,search_template,active from patient_education_resources where active order by title;";var x=new List<PatientEducationResource>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))x.Add(new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetBoolean(3)));return new(x);}public async Task<PatientEducationSearchResponse?> SearchAsync(PatientEducationSearchRequest x,CancellationToken ct){var text=x.SearchText?.Trim();if(string.IsNullOrWhiteSpace(text))return null;await using var c=await source.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="select search_template from patient_education_resources where resource_key=@key and active;";q.Parameters.AddWithValue("key",x.ResourceKey);var t=await q.ExecuteScalarAsync(ct) as string;var destination=t?.Replace("[%]",Uri.EscapeDataString(text));if(destination is null||!t!.Contains("[%]",StringComparison.Ordinal)||!Uri.TryCreate(destination,UriKind.Absolute,out var url)||url.Scheme!="https")return null;return new(x.ResourceKey,text,destination);}}
